# most_frequent :: [1, 2, 2, 3, 3, 3]
from collections import Counter

def most_frequent(xs):
    if not xs:
        return None
    return Counter(xs).most_common(1)[0][0]

if __name__ == '__main__':
    print(most_frequent([1, 2, 2, 3, 3, 3]))

